(()=>{const dialog=document.getElementById('listing-year-dialog'),form=document.getElementById('listing-year-form'),input=form.elements.namedItem('year'),message=document.getElementById('listing-year-message');let key=null,item=null;window.openListingYear=next=>{key=next;item=rows.find(x=>listingKey(x)===key)||savedState[key]?.snapshot;if(!item)return;input.value=listingYear(item);message.textContent='';dialog.showModal();input.focus()};document.getElementById('listing-year-close').addEventListener('click',()=>dialog.close());form.addEventListener('submit',event=>{event.preventDefault();if(!key||!item||!form.reportValidity())return;const year=input.value.trim();if(year&&(!/^\d{4}$/.test(year)||Number(year)<1000||Number(year)>2100)){message.textContent='Bitte ein vierstelliges Baujahr zwischen 1000 und 2100 eingeben.';return}const previous=savedState[key];savedState[key]={...previous,snapshot:previous?.snapshot||{...item},...(year?{year_override:year}:{})};if(!year)delete savedState[key].year_override;if(!saveState()){if(previous)savedState[key]=previous;else delete savedState[key];message.textContent='Das Baujahr konnte nicht gespeichert werden.';return}dialog.close();render();renderObjects()})})();
